        "testata": "BBC News",
        "lingua_originale": "en",
        "titolo_orig": "What we know about the ceasefire between Lebanon and Israel",
        "testo_it": "Cessate il fuoco tra Libano e Israele: accordo di 10 giorni annunciato dal Presidente USA Trump.",
        "priorita": "Alta",
        "id_gruppo": 4,
        "link": "https://www.bbc.com/news/articles/cwy32277e58o?at_medium=RSS&at_campaign=rss",
